import {riverView,validRiverCheck,validRiverKeep,validRiverModel,validRiverPart,validRiverAnswer,startRiver,resumeRiver,pageRiver,amountRiver,orderRiver,sortRiver,answerRiver,checkRiver,helpRiver,modelRiver,keepRiverModel,planRiver,starterRiver,keepRiverNote,removeRiver,riverRectangle,formatRiverNumber} from './river-room-core.mjs';
import {hearButton,stopSpeech} from './play-media.mjs';

const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const own=(x,k)=>x!==null&&typeof x==='object'&&Object.hasOwn(x,k);
const object=x=>x!==null&&typeof x==='object'&&!Array.isArray(x);
const get=(x,k,f='')=>own(x,k)?x[k]:f;
const list=x=>Array.isArray(x)?x:[];
const btn=(attrs,label,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
const para=text=>`<p>${esc(text)}</p>`;
const tag=(s,kind)=>`<p class="river-tag river-tag-${kind}">${esc(s.labels[kind])}</p>`;
const retained=label=>`<p class="river-retained" data-river-unreadable>${esc(label)} cannot be read here. Its exact saved form stays in your notebook download.</p>`;
const rawJSON=x=>{try{return JSON.stringify(x,null,2);}catch{return 'This retained value is unavailable.';}};
const known=(w,code)=>list(w.help).includes(code);
const safeURL=text=>{try{const u=new URL(text);return u.protocol==='https:'&&!u.username&&!u.password?u.href:null;}catch{return null;}};
function sourceCard(c){const url=safeURL(c.url);return `<article class="river-source-card"><h4>${esc(c.maker)}</h4><p><strong>${esc(c.type)}</strong> · ${esc(c.date)}</p><p>Purpose: ${esc(c.purpose)}</p><p>Supports: ${esc(c.supports)}</p><p>Limits: ${esc(c.limits)}</p><p>${esc(c.locator)} ${url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">Open this source</a>`:esc(c.url)}</p></article>`;}
function reference(w){const s=w.source;return `<details class="river-reference" data-river-panel="sources"><summary>Sources and words</summary>${tag(s,'history')}<p>This is a modern summary of official records. Agency accounts cannot replace displaced residents’ own accounts.</p><div class="river-source-list">${s.sources.filter(c=>c.id!=='design').map(c=>`<section>${btn(`data-river-help="source-${esc(c.id)}" aria-expanded="${known(w,`source-${c.id}`)}"`,`${c.maker} · ${c.type}`)}${known(w,`source-${c.id}`)?sourceCard(c):''}</section>`).join('')}</div><h3>Words in this book</h3>${s.glossary.map(g=>`<section>${btn(`data-river-help="glossary-${esc(g.id)}" aria-expanded="${known(w,`glossary-${g.id}`)}"`,g.term)}${known(w,`glossary-${g.id}`)?para(g.text):''}</section>`).join('')}</details>`;}
function reading(w,section){const s=w.source,passages=s.passages[section],selected=passages.find(p=>p.id===get(w.amounts,section))||passages[0];if(!selected)return '';const audio=hearButton(selected.text,'Hear this reading').replace('data-speak-lang=',`data-river-audio="audio-${esc(selected.id)}" data-speak-lang=`);return `<section class="river-reading">${tag(s,'history')}<div class="river-actions" role="group" aria-label="Reading amount">${passages.map(p=>btn(`data-river-amount="${esc(p.id)}" data-section="${section}" aria-pressed="${selected.id===p.id}"`,p.label)).join('')}</div><p class="river-reading-text">${esc(selected.text)}</p>${audio}</section>`;}
function teaching(w){const code=`page-${w.page}`,d=get(w.source.display,code,null);return d?`<aside class="river-teaching">${para(d.text)}</aside>`:'';}
function taskSupport(w,q){const s=w.source,ids=[q.hintId,q.exampleId].filter(id=>typeof id==='string'&&own(s.help,id));return `<div class="river-support"><div class="river-actions">${ids.map((id,i)=>btn(`data-river-help="${esc(id)}"`,i?'A different example':'A hint')).join('')}</div>${ids.filter(id=>known(w,id)).map(id=>`<aside class="river-help-shown" tabindex="-1" data-river-help-text="${esc(id)}"><h4>${esc(s.help[id].title)}</h4>${para(s.help[id].text)}</aside>`).join('')}</div>`;}
function checkTask(c){return c.kind==='order'?c.source.historyTask:c.kind==='sort'?c.source.sortTask:c.source.tasks.find(q=>q.id===c.taskId);}
function checkRaw(c){if(c.kind==='order')return list(c.raw.order).map(id=>{const t=c.source.timeline.find(t=>t.id===id);return t?`${t.year} · ${t.text}`:id;}).join('\n');if(c.kind==='sort')return c.source.measures.map(m=>`${m.title}: ${c.source.categories.find(k=>k.id===get(c.raw.assignments,m.id))?.label??'Not chosen'}`).join('\n');const q=checkTask(c);return list(q?.fields).map(f=>`${f.label}: ${get(c.raw.fields,f.id)} ${c.raw.unit}`).join('\n');}
function checkCard(c,label){const q=checkTask(c);return `<article class="river-check"><h4>${esc(label)}</h4><p>${esc(q?.prompt??c.taskId)}</p>${q?.context?`<p class="river-context">${esc(q.context)}</p>`:''}<p class="river-raw">${esc(checkRaw(c))}</p><p data-river-feedback>${esc(c.feedback)}</p><details><summary>Context kept with this response</summary><p>${esc(c.source.title)} · guided practice</p><p>Teaching available before this check: ${esc(list(c.shownBefore).map(code=>get(c.source.display,code)?.title??code).join('; ')||'None recorded')}.</p><p>Help requested before this check: ${esc(list(c.helpBefore).map(code=>get(c.source.help,code)?.title??code).join('; ')||'None requested')}.</p>${c.modelContext?para(`Rectangle at the time: width ${c.modelContext.width}; other side ${formatRiverNumber(c.modelContext.otherSide)}; area ${formatRiverNumber(c.modelContext.area)}.`):''}</details></article>`;}
function history(w,id){const matches=list(w.checks).filter(c=>object(c)&&own(c,'taskId')&&c.taskId===id),latest=matches.at(-1),first=get(w.firstChecks,id,null);return `<section class="river-result" id="river-result-${esc(id)}" tabindex="-1">${latest?(validRiverCheck(latest)?checkCard(latest,'Latest checked version'):retained('Latest checked version')):''}${own(w.firstChecks,id)?`<details data-river-panel="first-${esc(id)}"><summary>First checked version</summary>${validRiverCheck(first)?checkCard(first,'First checked version'):retained('First checked version')}</details>`:''}</section>`;}
function discussion(w,d){const s=w.source;return `<section class="river-discussion"><h3>${esc(d.prompt)}</h3>${d.page===0?d.sourceIds.map(id=>s.sources.find(c=>c.id===id)).filter(Boolean).map(sourceCard).join(''):d.sourceIds.length?`<details data-river-panel="discussion-sources-${esc(d.id)}"><summary>Records behind this question</summary>${d.sourceIds.map(id=>s.sources.find(c=>c.id===id)).filter(Boolean).map(sourceCard).join('')}</details>`:''}<div class="river-choices">${d.options.map(o=>btn(`data-river-help="discussion-${esc(d.id)}-${esc(o.id)}" aria-pressed="${known(w,`discussion-${d.id}-${o.id}`)}"`,o.label)).join('')}</div>${d.options.filter(o=>known(w,`discussion-${d.id}-${o.id}`)).map(o=>`<aside class="river-reply"><strong>${esc(o.label)}</strong>${para(o.reply)}</aside>`).join('')}</section>`;}
const discussions=(w,page)=>w.source.discussions.filter(d=>d.page===page).map(d=>discussion(w,d)).join('');
function recordPage(w){const s=w.source;return `<h2 id="river-heading" tabindex="-1">${esc(s.pages[0])}</h2>${reading(w,'history')}<ol class="river-timeline" aria-label="Program timeline">${s.timeline.map(t=>`<li><strong>${esc(t.year)}</strong><span>${esc(t.text)}</span></li>`).join('')}</ol>${teaching(w)}<section><h3>${esc(s.historyTask.prompt)}</h3><ol class="river-order">${list(w.order).map((id,i)=>{const event=s.timeline.find(t=>t.id===id);return event?`<li><p>${esc(event.year)} · ${esc(event.text)}</p><div class="river-actions">${btn(`data-river-order="${esc(id)}" data-direction="-1"${i===0?' disabled':''}`,'Move earlier')}${btn(`data-river-order="${esc(id)}" data-direction="1"${i===w.order.length-1?' disabled':''}`,'Move later')}</div></li>`:'';}).join('')}</ol>${btn(`data-river-check="${esc(s.historyTask.id)}"`,'Check against the timeline',true)}${history(w,s.historyTask.id)}</section>${discussions(w,0)}`;}
function measuresPage(w){const s=w.source;return `<h2 id="river-heading" tabindex="-1">${esc(s.pages[1])}</h2>${tag(s,'history')}${teaching(w)}<p>These cards compare two kinds of measure. Real projects can combine them. Strengthening a dike is different from raising it.</p><section><h3>${esc(s.sortTask.prompt)}</h3><div class="river-measures">${s.measures.map(m=>`<article><h4>${esc(m.title)}</h4>${para(m.text)}<label>Main described change<select data-river-sort="${esc(m.id)}"><option value="">Choose a kind</option>${s.categories.map(c=>`<option value="${esc(c.id)}"${get(w.sorted,m.id)===c.id?' selected':''}>${esc(c.label)}</option>`).join('')}</select></label></article>`).join('')}</div>${btn(`data-river-check="${esc(s.sortTask.id)}"`,'Check these choices',true)}${history(w,s.sortTask.id)}</section><section class="river-analogy"><h3>What resembles a town idea?</h3>${tag(s,'story')}<p>Choose a comparison to explore a likeness and a difference. These practice ideas do not choose the town’s plan.</p>${s.analogy.plans.map(p=>`<p><strong>${esc(p.label)}:</strong> ${esc(p.text)}</p>`).join('')}${s.analogy.measures.map(id=>{const m=s.measures.find(m=>m.id===id);if(!m)return '';return `<article><h4>${esc(m.title)}</h4><div class="river-choices">${s.analogy.plans.map(p=>btn(`data-river-help="analogy-${esc(id)}-${esc(p.id)}" aria-pressed="${known(w,`analogy-${id}-${p.id}`)}"`,p.label)).join('')}</div>${s.analogy.plans.filter(p=>known(w,`analogy-${id}-${p.id}`)).map(p=>`<aside class="river-reply">${para(get(get(s.analogy.replies,id,{}),p.id))}</aside>`).join('')}</article>`;}).join('')}</section>${discussions(w,1)}`;}
function numericTask(w,q){const raw=get(w.answers,q.id,{}),fields=get(raw,'fields',{}),readable=!own(w.answers,q.id)||validRiverAnswer(raw);if(!readable)return `<section class="river-numeric"><h3>${esc(q.prompt)}</h3>${retained('This question’s earlier draft')}${taskSupport(w,q)}${history(w,q.id)}</section>`;return `<section class="river-numeric" data-river-question="${esc(q.id)}"><h3>${esc(q.prompt)}</h3><p class="river-context">${esc(q.context)}</p><div class="river-fields">${q.fields.map(f=>`<label for="river-answer-${esc(q.id)}-${esc(f.id)}">${esc(f.label)}<input id="river-answer-${esc(q.id)}-${esc(f.id)}" type="text" inputmode="decimal" autocomplete="off" spellcheck="false" maxlength="40" data-river-field="${esc(f.id)}" data-task="${esc(q.id)}" data-river-draft value="${esc(get(fields,f.id))}"></label>`).join('')}<label>Unit<select data-river-unit data-task="${esc(q.id)}"><option value="">Choose a unit</option>${q.unitChoices.map(u=>`<option value="${esc(u.id)}"${get(raw,'unit')===u.id?' selected':''}>${esc(u.label)}</option>`).join('')}</select></label></div>${btn(`data-river-check="${esc(q.id)}"`,'Check this answer',true)}${taskSupport(w,q)}${history(w,q.id)}</section>`;}
function modelDrawing(g,width){const r=riverRectangle(g,width);if(!r)return '<p>This earlier rectangle cannot be drawn here.</p>';const span=Math.max(1,g.maxWidth-g.minWidth),drawWidth=70+(width-g.minWidth)/span*380,other=r.otherSide.n/r.otherSide.d,initial=riverRectangle(g,g.minWidth),drawHeight=20+Math.min(1,other/(initial.otherSide.n/initial.otherSide.d))*100;return `<svg viewBox="0 0 520 180" role="img" aria-label="Invented rectangle: width ${esc(width)} ${esc(g.labels.unit)}, other side ${esc(formatRiverNumber(r.otherSide))} ${esc(g.labels.unit)}, area ${esc(formatRiverNumber(r.area))} ${esc(g.labels.areaUnit)}. Horizontal and vertical drawing scales differ."><rect x="35" y="20" width="${drawWidth}" height="${drawHeight}" rx="2" fill="#c9dfe9" stroke="#173c51" stroke-width="2"/><path d="M35 155H${35+drawWidth}" stroke="#173c51"/><text x="35" y="174">Width ${esc(width)} ${esc(g.labels.unit)}</text></svg><dl class="river-model-values"><div><dt>${esc(g.labels.width)}</dt><dd>${esc(width)} ${esc(g.labels.unit)}</dd></div><div><dt>${esc(g.labels.otherSide)}</dt><dd>${esc(formatRiverNumber(r.otherSide))} ${esc(g.labels.unit)}</dd></div><div><dt>${esc(g.labels.area)}</dt><dd>${esc(formatRiverNumber(r.area))} ${esc(g.labels.areaUnit)}</dd></div></dl><p>Exact: ${esc(width)} × (${esc(formatRiverNumber(r.otherSide))}) = ${esc(formatRiverNumber(r.area))}.</p>${r.otherSide.d!==1?`<p>Approximate other side: ${esc(r.approx)} ${esc(g.labels.unit)} (rounded to two decimal places). The fraction above is exact; a fraction is division.</p>`:''}<p class="river-caption">${esc(g.labels.drawing)}</p>`;}
function modelSummary(m){return `<article class="river-model-summary"><h4>${esc(m.sourceTitle)}</h4><p>Width: ${esc(m.width)} ${esc(m.labels.unit)} · Other side: ${esc(formatRiverNumber(m.otherSide))} ${esc(m.labels.unit)} · Area: ${esc(formatRiverNumber(m.area))} ${esc(m.labels.areaUnit)}</p><p class="river-caption">${esc(m.labels.limit)}</p></article>`;}
function modelComparisons(w){const readable=list(w.models).filter(validRiverModel),unreadable=list(w.models).length-readable.length,models=readable.slice(-2);if(!models.length&&!unreadable)return '';const same=models.length===2&&models[0].area.n===models[1].area.n&&models[0].area.d===models[1].area.d&&models[0].labels.areaUnit===models[1].labels.areaUnit;return `<section><h3>Most recent readable rectangles</h3>${list(w.models).length&&!validRiverModel(list(w.models).at(-1))?retained('Latest rectangle record'):''}${same?'<p>These two rectangles have the same area. Compare their widths and other sides.</p>':'<p>Read the area and context of each rectangle before comparing them.</p>'}${models.map(modelSummary).join('')}${unreadable?retained(`${unreadable} retained rectangle record${unreadable===1?'':'s'}`):''}</section>`;}
function geometryPage(w){const s=w.source,g=s.geometry,tile=g.tile;return `<h2 id="river-heading" tabindex="-1">${esc(s.pages[2])}</h2>${tag(s,'geometry')}${teaching(w)}<section class="river-tile-example"><h3>Cover a small rectangle</h3><div class="river-tiles" role="img" aria-label="${esc(tile.rows)} rows of ${esc(tile.columns)} unit squares" style="grid-template-columns:repeat(${tile.columns},1fr);max-width:${Math.max(tile.columns*30,50)}px">${Array.from({length:tile.rows*tile.columns},()=>'<span></span>').join('')}</div><p>${esc(tile.rows)} rows × ${esc(tile.columns)} columns = ${esc(tile.rows*tile.columns)} square units. The squares cover the rectangle without gaps or overlaps. Multiplication finds the area; division finds a missing side.</p></section><section class="river-model"><h3>Keep the area, change the shape</h3><p>${esc(g.labels.limit)}</p><label for="river-width">${esc(g.labels.width)} in ${esc(g.labels.unit)}<input id="river-width" type="range" data-river-width min="${g.minWidth}" max="${g.maxWidth}" step="${g.step}" value="${w.modelWidth}" aria-valuetext="${esc(w.modelWidth)} ${esc(g.labels.unit)}"></label><div class="river-actions">${btn('data-river-width-step="-1"','Narrower')}${btn('data-river-width-step="1"','Wider')}</div><div data-river-model-drawing>${modelDrawing(g,w.modelWidth)}</div>${btn('data-river-keep-model','Keep this rectangle',true)}${modelComparisons(w)}</section>${s.tasks.filter(q=>q.page===2).map(q=>numericTask(w,q)).join('')}${discussions(w,2)}`;}
function lentSchematic(){return `<figure class="river-lent"><svg viewBox="0 0 600 220" role="img" aria-label="Original schematic of a river, a side channel and a dike moved inland at Lent. Not to scale; no distances can be read from this picture."><rect width="600" height="220" fill="#e7efe3"/><path d="M0 160Q180 100 300 155T600 145V220H0Z" fill="#4d86a2"/><path d="M75 135Q260 22 520 125" fill="none" stroke="#8bb6c9" stroke-width="24"/><path d="M50 63Q275 0 550 68" fill="none" stroke="#b7955b" stroke-width="8"/><path d="M50 107Q280 65 550 113" fill="none" stroke="#806c4b" stroke-width="3" stroke-dasharray="8 6"/><g fill="#173c51" font-size="15"><text x="20" y="201">River Waal</text><text x="218" y="91">Side channel</text><text x="190" y="24">Dike moved inland</text></g></svg><figcaption>Original schematic · not to scale. The old dike is dashed. This picture does not supply a drawing scale or a flood prediction.</figcaption></figure>`;}
function scaleCard(s){const n=s.scale?.metersPerCentimeter;if(!Number.isSafeInteger(n)||n<1||n>1000000)return '';return `<section class="river-scale"><h3>A separate paper practice scale</h3><p>On a hypothetical paper drawing, 1 cm represents ${n} m in the real place: 1:${100*n}. These bars pair the units; they do not measure physical centimeters on your screen.</p><div class="river-paired-bars" role="img" aria-label="Paired bars: 1 centimeter on a hypothetical paper drawing represents ${n} meters in the real place"><p><span></span>1 cm on paper</p><p><span></span>${n} m in the real place</p></div><p>This scale card is separate from the not-to-scale Lent schematic above. Divide meters by ${n} to find drawing centimeters. Multiply drawing centimeters by ${n} to find real meters.</p></section>`;}
function lentPage(w){const s=w.source;return `<h2 id="river-heading" tabindex="-1">${esc(s.pages[3])}</h2>${reading(w,'lent')}${lentSchematic()}${tag(s,'geometry')}${scaleCard(s)}${teaching(w)}${s.tasks.filter(q=>q.page===3).map(q=>numericTask(w,q)).join('')}${tag(s,'history')}<p>The following perspectives invite questions. They are not quotations or reports of how a particular person felt.</p>${discussions(w,3)}`;}
function keepCard(k,label){return `<article class="river-kept"><h3>${esc(label)}</h3>${tag(k.source,'story')}${k.renderedParts.map(p=>`<section><h4>${esc(p.title)}</h4><p class="river-written">${esc(p.text)||'<em>Left open</em>'}</p><p class="river-caption">${p.mode==='supplied'?'Ready-made words':'Own-writing draft'}${get(get(k.plan,p.id,{}),'starterUsed',null)===true?' · Ready-made starter used earlier':''}</p></section>`).join('')}<details data-river-panel="read-${label==='First note'?'first':'latest'}"><summary>Read your note</summary><p>A local reading page for this case.</p>${k.renderedParts.map(p=>`<h4>${esc(p.title)}</h4><p class="river-written">${esc(p.text)||'<em>Left open</em>'}</p>`).join('')}${para(k.closing)}</details>${k.models.length?`<details><summary>Rectangles kept with this note</summary>${k.models.map(modelSummary).join('')}</details>`:''}</article>`;}
function notePage(w){const s=w.source;return `<h2 id="river-heading" tabindex="-1">${esc(s.pages[4])}</h2>${tag(s,'story')}${teaching(w)}<p>Keep a thought, a difference and a cost to discuss. You can leave a part open. These words stay in this case.</p>${s.parts.map(p=>{const raw=get(w.plan,p.id,null),valid=!own(w.plan,p.id)||validRiverPart(raw),d=valid&&raw?raw:{mode:'own',own:'',choiceId:''},selected=p.options.find(o=>o.id===d.choiceId);return `<section class="river-note-part"><h3>${esc(p.title)}</h3>${!valid?retained('This part’s earlier draft'):''}${valid?`<div class="river-actions" role="group" aria-label="Writing mode for ${esc(p.title)}">${['own','supplied'].map(mode=>btn(`data-river-plan-mode="${mode}" data-part="${esc(p.id)}" aria-pressed="${d.mode===mode}"`,mode==='own'?'My writing draft':'Ready-made words')).join('')}</div><label>Choose ready-made words<select data-river-plan-choice="${esc(p.id)}"><option value="">Leave open</option>${p.options.map(o=>`<option value="${esc(o.id)}"${d.choiceId===o.id?' selected':''}>${esc(o.text)}</option>`).join('')}</select></label>${selected?`<blockquote class="river-supplied">${esc(selected.text)}</blockquote>`:d.choiceId?retained('Earlier ready-made choice'):''}${btn(`data-river-starter="${esc(p.id)}"${!selected?' disabled':''}`,'Use as a starting draft')}${d.starterUsed===true?'<p class="river-caption" data-river-starter-used>Ready-made starter used earlier. You can edit this draft.</p>':''}<label for="river-own-${esc(p.id)}">Your writing draft<textarea id="river-own-${esc(p.id)}" data-river-plan-own="${esc(p.id)}" data-river-draft maxlength="1600" rows="4">\n${esc(d.own)}</textarea></label><p class="river-caption">The ${d.mode==='supplied'?'ready-made choice':'own-writing draft'} will appear in your kept note. Both drafts stay available.</p>`:''}</section>`;}).join('')}${btn('data-river-keep-note','Keep this note',true)}<section id="river-note-result" tabindex="-1">${own(w,'kept')?(validRiverKeep(w.kept)?keepCard(w.kept,'Latest note'):retained('Latest note')):''}${own(w,'firstKept')?`<details data-river-panel="first-note"><summary>First kept note</summary>${validRiverKeep(w.firstKept)?keepCard(w.firstKept,'First note'):retained('First note')}</details>`:''}</section>`;}
function visits(v){return `<details data-river-panel="visits"><summary>Your visits (${v.visits.length})</summary><div class="river-actions">${v.visits.map(x=>x.readable?btn(`data-river-resume="${esc(x.id)}" aria-pressed="${v.current===x.id}"`,x.title||x.id):retained(`Visit ${x.title||x.id}`)).join('')}</div>${btn('data-river-start','Open a new visit')}</details>`;}
function grownups(v){const design=v.work?.source.sources.find(c=>c.id==='design');return `<details class="river-grownups" data-river-panel="grownups"><summary>Grown-ups · sources, evidence and notebook space</summary><p>Modern summaries, invented geometry and fictional-town ideas have separate labels. These are supported tasks, not grades, a complete curriculum strand or evidence of independent proficiency. Available passages do not establish that they were read. Requested help, prior examples and original first/latest responses stay separate; interpretations and notes are ungraded.</p><p>Each visit keeps at most 12 rectangle models and 32 checks; up to 16 visits stay available. No records are removed automatically. An unreadable record stays exact in your download, while healthy work remains open. Your writing follows the existing local save settings and is included in notes downloads.</p>${design?`<details data-river-panel="adult-design"><summary>Adult source note · design prediction</summary>${sourceCard(design)}</details>`:''}<a class="secondary" href="#notes">Open notes and download</a>${v.visits.length?`<label>Selected visit to remove<select data-river-remove-choice><option value="">Choose a visit</option>${v.visits.map(x=>`<option value="${esc(x.id)}">${esc(x.title||x.id)}${x.readable?'':' · unreadable'}</option>`).join('')}</select></label>${btn('data-river-remove','Remove only this visit')}`:''}</details>`;}
export const riverEntry=()=>'<section class="river-entry"><h2>Make room for a question</h2><p>Read a Dutch river record, reshape an invented rectangle and compare what a town could learn.</p><a class="secondary" href="#learn/history/river-room">Open Room for the River</a></section>';
export const riverRefusal=()=>'<section class="river-page"><h1>Room for the River</h1><h2>Earlier work is safe</h2><p>This page could not keep newly shown support safely. No new mathematics has been revealed. Download your notebook before making room, or choose another destination.</p><a class="secondary" href="#notes">Open notes and download</a><a class="secondary" href="#desk">Keeper’s Desk</a><a class="secondary" href="#pathways/science">Science starting points</a><p id="river-status" role="status" tabindex="-1"></p></section>';
export function riverPage(state){const v=riverView(state),w=v.work,head='<div class="river-page" data-river-root><header class="river-header"><a class="back" href="#desk">Back to the Keeper’s Desk</a><p class="river-kicker">A book with room for your ideas</p><h1>Room for the River</h1><p>Read a record. Change a rectangle. Keep a question for the town.</p></header>',status='<p id="river-status" role="status" aria-live="polite" tabindex="-1"></p><div data-river-pending-actions hidden><p>Your visible words have not been saved. Copy or edit the marked fields, or deliberately restore the saved words.</p>'+btn('data-river-restore','Restore saved words')+'</div>',foot='<footer><a href="#pathways/science">Science starting points</a><a href="#pathways/english">English starting points</a><a href="#science/water-shares">Hundred Cups</a><a href="#learn/science/records">The Town Record</a></footer></div>';
 if(v.status==='unavailable')return head+'<h2 id="river-heading" tabindex="-1">Earlier format retained</h2><p>This saved format cannot be edited here. Your original notebook is downloadable, and other places remain open.</p><a class="secondary" href="#notes">Open notes</a>'+status+foot;
 if(!w)return head+`<p class="river-tag">Story · Willowbank</p><h2 id="river-heading" tabindex="-1">The librarian opens a blue book</h2><p>“Other places have asked how to make room for a river. Shall we read one account, then think about what is different here?”</p><p>A modern summary of Dutch records, with separate invented geometry and fictional-town ideas. Choose any part after opening.</p>${v.status==='unreadable'?retained('Selected visit'):''}${btn('data-river-start','Open the book',true)}${v.visits.length?visits(v)+grownups(v):''}${status}${foot}`;
 const s=w.source,page=Math.max(0,Math.min(4,w.page));return head+`<p class="river-visit-title">${esc(s.title)}</p><nav class="river-pages" aria-label="Open parts of this book">${s.pages.map((name,i)=>btn(`data-river-page="${i}" aria-current="${page===i?'page':'false'}"`,name)).join('')}</nav><section class="river-turn">${[recordPage,measuresPage,geometryPage,lentPage,notePage][page](w)}</section><nav class="river-page-arrows" aria-label="Previous and next part">${page?btn(`data-river-page="${page-1}"`,`Previous: ${s.pages[page-1]}`):''}${page<4?btn(`data-river-page="${page+1}"`,`Next: ${s.pages[page+1]}`):''}</nav>${status}${list(w.checks).some(c=>!object(c)||!own(c,'taskId'))?retained('An earlier check with no readable question identity'):''}${reference(w)}${visits(v)}${grownups(v)}${foot}`;
}
export function riverNotes(state){if(!own(state,'riverRoom'))return '';const v=riverView(state);return `<details class="panel river-notes"><summary>Room for the River · history and invented geometry</summary><p>Source-owned visits, raw answers, requested support, original checks, rectangle models and first/latest notes remain separate. These records do not establish independent proficiency, historical interpretation or river-safety knowledge.</p>${v.status==='unavailable'?retained('Earlier format'):v.visits.map(x=>`<p>${esc(x.title||x.id)} · ${x.readable?'retained visit':'unreadable, retained exactly'}</p>`).join('')}<details><summary>Exact frozen sources and writing</summary><pre>${esc(rawJSON(state.riverRoom))}</pre></details></details>`;}

let removeGuards=()=>{},pendingNavigation=()=>false;
export const guardRiverNavigation=()=>pendingNavigation();
export function bindRiver(state,{save,render,focus,canExport,exposeFacts,explorerId,isActive}={}){
 removeGuards();removeGuards=()=>{};const root=document.querySelector('[data-river-root]');if(!root)return;
 const owner=explorerId?.(),route=location.hash,o={canExport,exposeFacts},dirty=new Set();
 const live=el=>root.isConnected&&el?.isConnected&&root.contains(el)&&document.querySelector('[data-river-root]')===root&&location.hash===route&&explorerId?.()===owner&&(!isActive||isActive());
 const say=(text,take=false)=>{const el=root.querySelector('#river-status');if(el){el.textContent=text;if(take)el.focus();}};
 const pendingMessage='Your visible words have not been saved. Copy or edit the marked fields, or choose Restore saved words before continuing.';
 const pendingUI=()=>{const el=root.querySelector('[data-river-pending-actions]');if(el)el.hidden=!dirty.size;};
 const redraw=(message='',target='#river-heading')=>{const panels=new Map([...root.querySelectorAll('details[data-river-panel]')].map(n=>[n.dataset.riverPanel,n.open]));stopSpeech();save?.();render?.();const next=document.querySelector('[data-river-root]');next?.querySelectorAll('details[data-river-panel]').forEach(n=>{if(panels.has(n.dataset.riverPanel))n.open=panels.get(n.dataset.riverPanel);});const status=next?.querySelector('#river-status');if(status)status.textContent=message;const node=next?.querySelector(target);if(node){node.focus();if(document.activeElement!==node)focus?.(target);}else focus?.('#river-heading');};
 const fail=()=>say('This change could not be kept safely. Earlier work stays unchanged. Download your notes before making room, or choose another visit.',true);
 const act=(el,fn,message='',target='#river-heading')=>{if(!live(el))return false;if(dirty.size){say(pendingMessage,true);return false;}const r=fn();if(!r)return fail();if(r.recorded===false){say(r.feedback,true);return false;}redraw(message,target);return true;};
 const on=(selector,fn)=>root.querySelectorAll(selector).forEach(el=>el.addEventListener('click',()=>{if(live(el))fn(el);}));
 on('[data-river-start]',el=>act(el,()=>startRiver(state,o),'A visit is open. Choose any part.'));
 on('[data-river-resume]',el=>act(el,()=>resumeRiver(state,el.dataset.riverResume,o),'Original source and work resumed.'));
 on('[data-river-page]',el=>act(el,()=>pageRiver(state,Number(el.dataset.riverPage),o)));
 on('[data-river-amount]',el=>act(el,()=>amountRiver(state,el.dataset.section,el.dataset.riverAmount,o),'Reading amount kept.'));
 on('[data-river-order]',el=>act(el,()=>orderRiver(state,el.dataset.riverOrder,Number(el.dataset.direction),o),'Event moved.',`[data-river-order="${el.dataset.riverOrder}"][data-direction="${el.dataset.direction}"]`));
 on('[data-river-check]',el=>act(el,()=>checkRiver(state,el.dataset.riverCheck,o),'Original response kept.',`#river-result-${el.dataset.riverCheck}`));
 on('[data-river-help]',el=>act(el,()=>helpRiver(state,el.dataset.riverHelp,o),'Requested material is open.',`[data-river-help="${el.dataset.riverHelp}"]`));
 on('[data-river-keep-model]',el=>act(el,()=>keepRiverModel(state,o),'Rectangle kept with its own area and context.','[data-river-keep-model]'));
 on('[data-river-plan-mode]',el=>act(el,()=>planRiver(state,el.dataset.part,'mode',el.dataset.riverPlanMode,o),'Both drafts remain available.',`[data-river-plan-mode="${el.dataset.riverPlanMode}"][data-part="${el.dataset.part}"]`));
 on('[data-river-starter]',el=>{const id=el.dataset.riverStarter,d=get(riverView(state).work?.plan,id,{});if(dirty.size)return say(pendingMessage,true);const confirmed=typeof d.own==='string'&&d.own.length?window.confirm('Replace this part’s nonempty own-writing draft with the selected ready-made words? Cancel keeps both drafts unchanged.'):false;if(d.own?.length&&!confirmed)return;act(el,()=>starterRiver(state,id,confirmed,o),'Ready-made words copied into your own-writing draft.',`#river-own-${id}`);});
 on('[data-river-keep-note]',el=>act(el,()=>keepRiverNote(state,o),'Note kept. It may leave parts open.','#river-note-result'));
 on('[data-river-remove]',el=>{if(dirty.size)return say(pendingMessage,true);const id=root.querySelector('[data-river-remove-choice]')?.value;if(!id)return say('Choose one visit to remove.',true);if(!window.confirm('Remove only this selected visit, including its sources, models, writing and checks? Download notes first if you want a copy.'))return;act(el,()=>removeRiver(state,id,true,o),'Selected visit removed. Other work stays available.');});
 const select=(selector,fn,stored,target=()=>selector)=>root.querySelectorAll(selector).forEach(el=>el.addEventListener('change',()=>{if(!live(el))return;const old=stored(el);if(dirty.size){el.value=old;say(pendingMessage,true);return;}if(!act(el,()=>fn(el),'Choice kept.',target(el)))el.value=old;}));
 select('[data-river-sort]',el=>sortRiver(state,el.dataset.riverSort,el.value,o),el=>get(riverView(state).work?.sorted,el.dataset.riverSort),el=>`[data-river-sort="${el.dataset.riverSort}"]`);
 select('[data-river-unit]',el=>answerRiver(state,el.dataset.task,'unit',el.value,o),el=>get(get(riverView(state).work?.answers,el.dataset.task,{}),'unit'),el=>`[data-river-unit][data-task="${el.dataset.task}"]`);
 select('[data-river-plan-choice]',el=>planRiver(state,el.dataset.riverPlanChoice,'choiceId',el.value,o),el=>get(get(riverView(state).work?.plan,el.dataset.riverPlanChoice,{}),'choiceId'),el=>`[data-river-plan-choice="${el.dataset.riverPlanChoice}"]`);
 const input=(el,key,fn)=>el.addEventListener('input',()=>{if(!live(el))return;if(!fn(el.value)){dirty.add(key);el.setAttribute('aria-invalid','true');pendingUI();say(pendingMessage);return;}dirty.delete(key);el.removeAttribute('aria-invalid');save?.();pendingUI();say(dirty.size?pendingMessage:'Words saved.');});
 root.querySelectorAll('[data-river-field]').forEach(el=>input(el,`answer-${el.dataset.task}-${el.dataset.riverField}`,raw=>answerRiver(state,el.dataset.task,el.dataset.riverField,raw,o)));
 root.querySelectorAll('[data-river-plan-own]').forEach(el=>input(el,`note-${el.dataset.riverPlanOwn}`,raw=>planRiver(state,el.dataset.riverPlanOwn,'own',raw,o)));
 const updateModel=(el,width)=>{if(!live(el))return;if(dirty.size){const slider=root.querySelector('[data-river-width]');if(slider)slider.value=riverView(state).work.modelWidth;return say(pendingMessage,true);}const before=riverView(state).work;if(!before)return;const old=before.modelWidth;if(!modelRiver(state,width,o)){const slider=root.querySelector('[data-river-width]');if(slider)slider.value=old;return fail();}save?.();const w=riverView(state).work,slider=root.querySelector('[data-river-width]'),drawing=root.querySelector('[data-river-model-drawing]');if(slider){slider.value=w.modelWidth;slider.setAttribute('aria-valuetext',`${w.modelWidth} ${w.source.geometry.labels.unit}`);}if(drawing)drawing.innerHTML=modelDrawing(w.source.geometry,w.modelWidth);say('Rectangle changed; its area stays fixed.');};
 root.querySelector('[data-river-width]')?.addEventListener('input',e=>updateModel(e.currentTarget,Number(e.currentTarget.value)));
 on('[data-river-width-step]',el=>{const w=riverView(state).work;if(!w)return;const g=w.source.geometry,width=Math.max(g.minWidth,Math.min(g.maxWidth,w.modelWidth+Number(el.dataset.riverWidthStep)*g.step));updateModel(el,width);});
 on('[data-river-restore]',el=>{if(!live(el)||!window.confirm('Discard visible unsaved edits and restore the last saved words? Earlier saved work stays unchanged.'))return;const w=riverView(state).work;if(!w)return;root.querySelectorAll('[data-river-field]').forEach(field=>{field.value=get(get(get(w.answers,field.dataset.task,{}),'fields',{}),field.dataset.riverField);field.removeAttribute('aria-invalid');});root.querySelectorAll('[data-river-plan-own]').forEach(field=>{field.value=get(get(w.plan,field.dataset.riverPlanOwn,{}),'own');field.removeAttribute('aria-invalid');});dirty.clear();pendingUI();say('Last saved words restored.',true);});
 // Capture executes before the shared hearButton listener, including detached/stale controls.
 root.addEventListener('click',e=>{const el=e.target.closest?.('[data-speak]');if(!el)return;const code=el.dataset.riverAudio;if(!live(el)||dirty.size||!code){e.preventDefault();e.stopImmediatePropagation();if(dirty.size)say(pendingMessage,true);return;}if(!helpRiver(state,code,o)){e.preventDefault();e.stopImmediatePropagation();fail();return;}save?.();},true);
 const guard=e=>{if(e.type==='keydown'&&!['Enter',' '].includes(e.key))return;if(!root.isConnected||location.hash!==route||explorerId?.()!==owner||!dirty.size)return;const target=e.target;if(target?.closest?.('[data-river-draft],[data-river-restore]'))return;if(target?.closest?.('button,a,input,select,summary')){e.preventDefault();e.stopImmediatePropagation();say(pendingMessage,true);}};
 pendingNavigation=()=>{if(!root.isConnected||explorerId?.()!==owner||!dirty.size)return false;window.history.replaceState(null,'',route);say(pendingMessage,true);return true;};
 const beforeLeave=e=>{if(dirty.size&&root.isConnected){e.preventDefault();e.returnValue='';}};
 document.addEventListener('click',guard,true);document.addEventListener('keydown',guard,true);window.addEventListener('beforeunload',beforeLeave);
 removeGuards=()=>{document.removeEventListener('click',guard,true);document.removeEventListener('keydown',guard,true);window.removeEventListener('beforeunload',beforeLeave);pendingNavigation=()=>false;};
}
